import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    lengths = [int(x) for x in data[1:n+1]]

    if len(lengths) != n:
        print("NO")
        return

    sorted_lengths = sorted(lengths)
    current_max = 0
    for i, l in enumerate(sorted_lengths):
        if l <= current_max:
            print("NO")
            return
        current_max = l - 1

    words = [""] * n
    used = set()

    for idx, l in enumerate(lengths):
        word = ""
        node = 0
        for _ in range(l):
            if node * 2 + 1 not in used:
                word += "0"
                node = node * 2 + 1
            else:
                word += "1"
                node = node * 2 + 2
        words[idx] = word
        used.add(node)

    print("YES")
    for w in words:
        print(w)

if __name__ == "__main__":
    main()
